INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'afghanistan'), 0, 'Afghanistan hat derzeit keine legal vermarktete nationale Spirituosenmarke. Die Weltgesundheitsorganisation führt das Land mit einem vollständigen Verbot für alkoholische Getränke.', 'Afghanistan currently has no legally marketed national spirits brand. The World Health Organization lists the country as having a total ban on alcoholic beverages.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'afghanistan'), 1, 'Auch der Verkauf und Transport von Alkohol werden aktuell verfolgt: Das afghanische Innenministerium berichtete 2025 über Festnahmen und beschlagnahmte alkoholische Getränke in Kabul.', 'The sale and transport of alcohol are also currently prosecuted: in 2025, the Afghan Ministry of Interior reported arrests and the seizure of alcoholic beverages in Kabul.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'afghanistan'), 2, 'Deshalb weisen wir Afghanistan transparent aus, bieten aber weder Low-, Standard- noch Premiumprodukte an. Nicht registrierte oder privat gebrannte Erzeugnisse kommen wegen Rechtslage, Herkunft und Produktsicherheit nicht für den Verkauf infrage.', 'We therefore list Afghanistan transparently but offer no Low, Standard or Premium products. Unregistered or privately distilled products are not considered for sale because of the legal situation, provenance and product safety.');
