INSERT INTO countries (slug, name_de, name_en, status, alkoholverbot, sort_order, spirit_de, spirit_en, subtitle_de, subtitle_en, notice_de, notice_en, glow_rgb, stroke_hex, fill_hex, hover_fill_hex, dark_fill_hex, dark_hover_hex, glow_delay) VALUES ('china', 'China', 'China', 'veroeffentlicht', '0', '2', 'Baijiu', 'Baijiu', 'Chinas bekannteste Spirituose', 'China’s best-known spirit', NULL, NULL, '168 111 107', '#9c6865', '#f5eceb', '#ead6d4', '#211717', '#321f1e', '-1.1s');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'china'), 0, 'Baijiu ist eine traditionelle chinesische Getreidespirituose. Sie wird unter anderem aus Sorghum, Weizen oder Reis hergestellt und nicht nach dem Ausgangsgetreide, sondern nach ihrem Aroma eingeteilt.', 'Baijiu is a traditional Chinese grain spirit. It is made from ingredients including sorghum, wheat or rice and is classified by aroma rather than by its base grain.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'china'), 1, 'In China wird Baijiu meist pur aus kleinen Gläsern zu gemeinsamen Mahlzeiten und feierlichen Trinksprüchen serviert. Der berühmteste Vertreter ist Kweichow Moutai aus der Provinz Guizhou.', 'In China, baijiu is usually served neat in small glasses with shared meals and ceremonial toasts. Its most famous representative is Kweichow Moutai from Guizhou province.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'china'), 2, 'Unsere erste Herstellerwahl ist Kweichow Moutai Co., Ltd. mit Yingbin Purple, Golden Prince und Flying Fairy. Als zweite Herstelleralternative ergänzen wir Wuliangye Yibin Co., Ltd. mit Wuliang Chun Mellow, Wuliang Chun Spring und dem Flaggschiff Wuliangye. Die dritte etablierte Wahl ist Luzhou Laojiao Co., Ltd. mit Touqu D9, Tequ Laojiu und Guojiao 1573 Classic.', 'Our first producer selection is Kweichow Moutai Co., Ltd. with Yingbin Purple, Golden Prince and Flying Fairy. Our second producer alternative is Wuliangye Yibin Co., Ltd. with Wuliang Chun Mellow, Wuliang Chun Spring and the flagship Wuliangye. The third established choice is Luzhou Laojiao Co., Ltd. with Touqu D9, Tequ Laojiu and Guojiao 1573 Classic.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'china'), 3, 'Moutai steht für Sauce Aroma auf Basis von rotem Sorghum und Weizen. Wuliangye vertritt den Strong-Aroma-Stil mit fünf Getreidearten. Luzhou Laojiao gilt als Wegbereiter des Strong-Aroma-Baijiu und führt seine Brenntradition über 700 Jahre zurück.', 'Moutai represents sauce aroma based on red sorghum and wheat. Wuliangye represents the strong-aroma style with five grains. Luzhou Laojiao is regarded as a pioneer of strong-aroma baijiu and traces its distilling tradition back more than 700 years.');
INSERT INTO facts (country_id, position, label_de, label_en, value_de, value_en) VALUES ((SELECT id FROM countries WHERE slug = 'china'), 0, 'Spirituose', 'Spirit', 'Baijiu', 'Baijiu');
