INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 0, 'Arak ist eine klare, ungesüßte Anisspirituose aus der Levante. In Israel wird sie häufig mit Wasser und Eis serviert. Dabei wird der klare Brand durch das ätherische Anisöl milchig weiß.', 'Arak is a clear, unsweetened anise spirit from the Levant. In Israel, it is often served with water and ice. The essential anise oil then turns the clear spirit milky white.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 1, 'Unsere erste Herstellerwahl ist Joseph Gold & Sons, dessen Familiengeschichte bis 1824 zurückreicht, mit Elite Arak, Amir Ha’Arak und Alouf Arak. Als zweite etablierte Alternative folgt die Familienbrennerei Kawar mit Kawar 40, Kawar 45 und Kawar Special 53. Die dritte Wahl ist ZOARA Distillery mit modernem Arak aus Medjool-Datteln.', 'Our first producer selection is Joseph Gold & Sons, whose family history dates back to 1824, with Elite Arak, Amir Ha’Arak and Alouf Arak. The second established alternative is the Kawar family distillery with Kawar 40, Kawar 45 and Kawar Special 53. The third choice is ZOARA Distillery with modern arak made from Medjool dates.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 2, 'Joseph Gold prägt den israelischen Arak-Markt mit klassischen Anisbränden. Kawar verbindet Traubenalkohol aus Galiläa mit syrischem Anis. ZOARA destilliert dagegen Medjool-Datteln aus dem Jordantal und ergänzt Anis mit frischem Estragon.', 'Joseph Gold has shaped Israel’s arak market with classic anise spirits. Kawar combines grape spirit from Galilee with Syrian anise. ZOARA instead distils Medjool dates from the Jordan Valley and complements the anise with fresh tarragon.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 3, 'Traditionell wird ein Teil Arak mit ungefähr zwei Teilen Wasser verdünnt und anschließend über Eis gegossen. Er begleitet Mezze, salzige Speisen und lange gemeinsame Mahlzeiten.', 'Traditionally, one part arak is diluted with about two parts water and then poured over ice. It accompanies mezze, savoury dishes and long shared meals.');
INSERT INTO facts (country_id, position, label_de, label_en, value_de, value_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 0, 'Spirituose', 'Spirit', 'Arak', 'Arak');
INSERT INTO facts (country_id, position, label_de, label_en, value_de, value_en) VALUES ((SELECT id FROM countries WHERE slug = 'israel'), 1, 'Stil', 'Style', 'Ungesüßte Anisspirituose', 'Unsweetened anise spirit');
