INSERT INTO countries (slug, name_de, name_en, status, alkoholverbot, sort_order, spirit_de, spirit_en, subtitle_de, subtitle_en, notice_de, notice_en, glow_rgb, stroke_hex, fill_hex, hover_fill_hex, dark_fill_hex, dark_hover_hex, glow_delay) VALUES ('russland', 'Russland', 'Russia', 'veroeffentlicht', '0', '4', 'Wodka', 'Vodka', 'Russlands bekannteste Spirituose', 'Russia’s best-known spirit', 'Die Einfuhr russischer Spirituosen in die Europäische Union ist derzeit untersagt. Das Produkt wird deshalb redaktionell vorgestellt, aber nicht zum Kauf angeboten.', 'The import of Russian spirits into the European Union is currently prohibited. These products are therefore presented editorially but are not offered for sale.', '111 129 157', '#687a94', '#edf0f5', '#d9deea', '#171b23', '#222a38', '-2.5s');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'russland'), 0, 'Wodka ist die international bekannteste Spirituose Russlands. Der klare Getreidebrand wird traditionell möglichst rein und neutral hergestellt und meist gut gekühlt, pur und zu Speisen serviert.', 'Vodka is Russia’s internationally best-known spirit. The clear grain spirit is traditionally produced to be as pure and neutral as possible and is usually served well chilled, neat and with food.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'russland'), 1, 'Unsere erste Herstellerwahl ist Russian Standard Vodka LLC mit Original, Gold und Platinum. Als zweite Herstelleralternative ergänzen wir die LADOGA Group aus Sankt Petersburg mit Czar’s Original, Czar’s Gold und Imperial Collection Golden Snow. Die dritte etablierte Wahl ist Tatspirtprom JSC aus Kasan mit Tundra Authentic, Tundra Frozen Juniper und Tundra Forest Woody Notes.', 'Our first producer selection is Russian Standard Vodka LLC with Original, Gold and Platinum. Our second producer alternative is the LADOGA Group from Saint Petersburg with Czar’s Original, Czar’s Gold and Imperial Collection Golden Snow. The third established choice is Tatspirtprom JSC from Kazan with Tundra Authentic, Tundra Frozen Juniper and Tundra Forest Woody Notes.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'russland'), 2, 'Russian Standard basiert auf Winterweizen und Wasser aus dem Ladogasee. LADOGA verbindet Getreidealkohol und besonders weiches Wasser. Tundra verwendet Alkohol der Klasse Alpha und entwickelt die höheren Stufen mit Wacholder, Pinienkernen, Kräutern und weiteren Pflanzenessenzen.', 'Russian Standard is based on winter wheat and water from Lake Ladoga. LADOGA combines grain spirit with particularly soft water. Tundra uses Alpha-grade spirit and develops its higher tiers with juniper, pine nuts, herbs and other botanical essences.');
INSERT INTO facts (country_id, position, label_de, label_en, value_de, value_en) VALUES ((SELECT id FROM countries WHERE slug = 'russland'), 0, 'Spirituose', 'Spirit', 'Wodka', 'Vodka');
