INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'japan'), 0, 'Sake ist Japans bekanntestes alkoholisches Getränk, aber keine Spirituose: Er wird gebraut und nicht destilliert. Die traditionelle japanische Spirituose ist Shōchū, ein klarer Brand aus regionalen Zutaten wie Gerste, Süßkartoffeln oder Reis.', 'Sake is Japan’s best-known alcoholic drink, but it is not a spirit: it is brewed, not distilled. Japan’s traditional spirit is shochu, a clear distillate made from regional ingredients such as barley, sweet potatoes or rice.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'japan'), 1, 'Unsere erste Herstellerwahl ist Sanwa Shurui Co., Ltd. mit der gerstenbasierten iichiko-Familie. Als zweite Herstelleralternative ergänzen wir Kirishima Shuzo Co., Ltd. mit Kuro Kirishima, Aka Kirishima und Kuro Kirishima MELT. Die dritte etablierte Wahl ist Takara Shuzo Co., Ltd. mit Takara Shochu Jun, Ikkomon und Ikkomon Long-Term Aged Genshu.', 'Our first producer selection is Sanwa Shurui Co., Ltd. with the barley-based iichiko family. Our second producer alternative is Kirishima Shuzo Co., Ltd. with Kuro Kirishima, Aka Kirishima and Kuro Kirishima MELT. The third established choice is Takara Shuzo Co., Ltd. with Takara Shochu Jun, Ikkomon and Ikkomon Long-Term Aged Genshu.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'japan'), 2, 'iichiko basiert auf Gerste und Gersten-Kōji. Kirishima verwendet Süßkartoffeln aus Kyūshū und Reis-Kōji. Takara Shuzo braut und destilliert seit 1842; Ikkomon wird vollständig aus Süßkartoffeln einschließlich Süßkartoffel-Kōji hergestellt.', 'iichiko is based on barley and barley koji. Kirishima uses sweet potatoes from Kyushu and rice koji. Takara Shuzo has brewed and distilled since 1842; Ikkomon is made entirely from sweet potatoes, including sweet-potato koji.');
INSERT INTO paragraphs (country_id, position, text_de, text_en) VALUES ((SELECT id FROM countries WHERE slug = 'japan'), 3, 'Traditionell wird Shōchū pur, auf Eis, mit kaltem oder heißem Wasser sowie als leichter Highball mit Soda serviert. Durch seinen zurückhaltenden Charakter passt Silhouette zu vielen Speisen.', 'Shochu is traditionally served neat, on ice, with cold or hot water, or as a light highball with soda. Silhouette’s restrained character makes it a versatile food companion.');
